SELECT ticker, MAX(name) AS name, COUNT(*) AS days_in_top, ROUND(AVG(composite_score), 1) AS avg_score,
       MIN(snapshot_date) AS first_date, MAX(snapshot_date) AS last_date
FROM m_stock_snapshot
WHERE market = {{market}} AND composite_score >= {{min_score}}
  AND snapshot_date >= (SELECT MAX(snapshot_date) FROM m_stock_snapshot) - {{days}}
GROUP BY ticker
HAVING COUNT(*) >= {{min_days}}
ORDER BY days_in_top DESC, avg_score DESC
LIMIT 50
